-- Runs only in a transaction; no customer or catalog mutation survives ROLLBACK.
begin;
do $$declare u uuid;v template_versions;i invitations;o website_orders;a jsonb;b jsonb;expiry timestamptz;blocked boolean;begin
 select id into u from auth.users order by created_at limit 1;
 if u is null then raise exception 'Requires an existing auth user for a rolled-back fixture';end if;
 select * into v from template_versions where template_id='christian-bells' order by revision desc limit 1;
 update template_versions set approved_at=now(),approved_by=u where id=v.id;
 update template_catalog set isactive=true,published=true,current_version_id=v.id where id=v.template_id;
 insert into invitations(slug,owner_id,template_version_id,management_hash,data,draft_content,expires_at,published) values('cms-transaction-test-'||substr(gen_random_uuid()::text,1,8),u,v.id,repeat('a',64),'{}',v.defaults,now()+interval '90 days',false) returning * into i;
 a:=fmi_reserve_website_order(i.id,u,'publish',0);b:=fmi_reserve_website_order(i.id,u,'publish',0);
 if not (a->>'created')::boolean or (b->>'created')::boolean or a->'order'->>'id'<>b->'order'->>'id' then raise exception 'Order reservation is not idempotent';end if;
 select * into o from website_orders where id=(a->'order'->>'id')::uuid;
 blocked:=false;begin perform fmi_publish_invitation(i.slug,u,0,o.id,false);exception when others then blocked:=true;end;if not blocked then raise exception 'Uncaptured order published';end if;
 update website_orders set status='captured' where id=o.id;
 a:=fmi_publish_invitation(i.slug,u,0,o.id,false);expiry:=(a->>'expires_at')::timestamptz;
 if a->'published_content'<>v.defaults or (a->>'first_published_at') is null then raise exception 'First publication failed';end if;
 b:=fmi_publish_invitation(i.slug,u,0,o.id,false);if (b->>'expires_at')::timestamptz<>expiry then raise exception 'Retry extended entitlement';end if;
 a:=fmi_save_draft(i.slug,u,0,jsonb_set(v.defaults,'{groom}','"Draft-only name"'));
 if a->'published_content'<>v.defaults then raise exception 'Draft mutated published content';end if;
 blocked:=false;begin perform fmi_save_draft(i.slug,u,0,v.defaults);exception when others then blocked:=true;end;if not blocked then raise exception 'Stale revision accepted';end if;
 blocked:=false;begin perform fmi_save_draft(i.slug,gen_random_uuid(),1,v.defaults);exception when others then blocked:=true;end;if not blocked then raise exception 'Wrong owner accepted';end if;
 a:=fmi_publish_invitation(i.slug,u,1,null,false);if a->'published_content'->>'groom'<>'Draft-only name' or (a->>'expires_at')::timestamptz<>expiry then raise exception 'Republish failed or extended hosting';end if;
 a:=fmi_reserve_website_order(i.id,u,'renew',0);update website_orders set status='captured' where id=(a->'order'->>'id')::uuid;
 b:=fmi_publish_invitation(i.slug,u,1,(a->'order'->>'id')::uuid,true);
 if (b->>'expires_at')::timestamptz<>((expiry at time zone 'UTC')+interval '6 months') at time zone 'UTC' then raise exception 'Early renewal base incorrect';end if;
 update invitations set expires_at=now()-interval '1 day' where id=i.id;
 a:=fmi_reserve_website_order(i.id,u,'renew',0);update website_orders set status='captured' where id=(a->'order'->>'id')::uuid;
 b:=fmi_publish_invitation(i.slug,u,1,(a->'order'->>'id')::uuid,true);
 if (b->>'expires_at')::timestamptz<>((now() at time zone 'UTC')+interval '6 months') at time zone 'UTC' then raise exception 'Late renewal base incorrect';end if;
 if ('2027-08-31 12:00:00'::timestamp+interval '6 months')<>'2028-02-29 12:00:00'::timestamp or ('2026-08-31 12:00:00'::timestamp+interval '6 months')<>'2027-02-28 12:00:00'::timestamp then raise exception 'Calendar clamp incorrect';end if;
 blocked:=false;begin update invitations set template_version_id=null where id=i.id;exception when others then blocked:=true;end;if not blocked then raise exception 'Purchased template changed';end if;
 blocked:=false;begin update template_versions set defaults='{}' where id=v.id;exception when others then blocked:=true;end;if not blocked then raise exception 'Version mutation accepted';end if;
 update invitations set expires_at=now()-interval '91 days' where id=i.id;
 blocked:=false;begin perform fmi_reserve_website_order(i.id,u,'renew',0);exception when others then blocked:=true;end;if not blocked then raise exception 'Renewal after recovery period accepted';end if;
 perform fmi_claim_retention(50);select * into i from invitations where id=i.id;
 if i.deleted_at is null or i.draft_content is not null or i.published_content is not null then raise exception 'Customer content not cleared';end if;
 if not exists(select 1 from website_orders where invitation_id=i.id) then raise exception 'Retention deleted transaction records';end if;
end$$;
select 'PASS: reservation, payment gate, idempotence, ownership, revisions, publication, calendar expiry, renewal, immutable releases, retention' as result;
rollback;
